import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { respondPoll } from "../handlers/respondPoll";
import type { ApiError } from "../runtime/client";
import type { RespondPollRequest } from "../types/RespondPollRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePollEntityType } from "../types/SpacePollEntityType";

type Data = Awaited<ReturnType<typeof respondPoll>>;
type Vars = { spacePk: SpacePartition; pollSk: SpacePollEntityType; req: RespondPollRequest };

export function useRespondPoll(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => respondPoll(vars.spacePk, vars.pollSk, vars.req),
    ...options,
  });
}
